import{_ as a,o as i,c as o,ag as l}from"./chunks/framework.DQQHyi2x.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),t={name:"changelog.md"};function r(n,e,s,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Claude Deck are documented here. The format follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>.</p><h2 id="_2-0-0-—-2026-06-19" tabindex="-1">2.0.0 — 2026-06-19 <a class="header-anchor" href="#_2-0-0-—-2026-06-19" aria-label="Permalink to &quot;2.0.0 — 2026-06-19&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Agent Mail</strong> for durable local coordination between Claude Code and Codex CLI sessions: <ul><li>Per-repo and Agent Team slot participants</li><li>Structured context requests, handoffs, replies, inbox state, and acknowledgements</li><li>Agent-facing MCP tools and one-click MCP/hooks install flows</li><li>Best-effort tmux wake nudges for visible sessions</li></ul></li><li><strong>Agent Teams</strong> for saved project, DevOps, release, and same-repo rosters: <ul><li>Manual team creation</li><li>Team creation from Agent Mail members or visible Agent Bridge sessions</li><li>Launch planning, reusable tmux sessions, slot roles, charters, bootstrap prompts, and provider options</li></ul></li><li><strong>External local orchestration</strong> through token-bound Agent Mail endpoints for tools such as OpenClaw.</li><li><strong>Agent Bridge session creation improvements</strong>: <ul><li>Searchable project picker</li><li>Codex model and profile selectors with custom fallback values</li></ul></li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Agent Bridge, Agent Mail, and Agent Teams are now the supported surfaces for local agent visibility and coordination.</li><li>Agent Mail status labels now distinguish connected, observed-only, not wakeable, inbox load, and current wake behavior more clearly.</li><li>Agent Mail documentation now explains MCP/hooks setup and the current tmux-only wake path.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><strong>Presence</strong> has been removed from the frontend, backend, hooks, and navigation. Agent Bridge, Agent Mail, and Agent Teams replace its intended observability role.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Agent Mail install/uninstall actions now refresh status and provide clearer feedback.</li><li>Agent Mail member counts now distinguish durable participants from observed sessions.</li><li>Claude Code and Codex Agent Mail hooks now return provider-valid JSON during normal mailbox checks.</li></ul><h2 id="_1-3-1-—-2026-06-11" tabindex="-1">1.3.1 — 2026-06-11 <a class="header-anchor" href="#_1-3-1-—-2026-06-11" aria-label="Permalink to &quot;1.3.1 — 2026-06-11&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Aligned <code>react</code> and <code>react-is</code> with the installed React DOM version to avoid production render failures from mixed React package versions.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Refreshed README screenshots, including the Agent Bridge mixed-provider view, dashboard, config, and MCP visuals used for the release.</li></ul><h2 id="_1-3-0-—-2026-06-08" tabindex="-1">1.3.0 — 2026-06-08 <a class="header-anchor" href="#_1-3-0-—-2026-06-08" aria-label="Permalink to &quot;1.3.0 — 2026-06-08&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Codex CLI support</strong> is now stable enough for daily use: <ul><li>Mixed Claude Code and Codex tmux sessions in Agent Bridge</li><li>Codex spawn, resume, fork, attach, and kill actions</li><li>Provider-aware navigation so Codex users do not land on unsupported Claude-only pages</li></ul></li><li><strong>Codex Config</strong>: <ul><li>Safe TOML editing for whitelisted scalar settings and feature flags</li><li>Dropdowns for known Codex runtime values</li><li>Help tooltips for documented settings and feature flags</li><li>Feature inventory from <code>codex features list</code>, including goals and other enable-flag features</li><li>Profile diagnostics for active/default profiles, profile files, overrides, missing references, and malformed profiles</li></ul></li><li><strong>Codex MCP and Plugins</strong>: <ul><li>MCP inventory from <code>codex mcp list --json</code></li><li>MCP add/remove through the Codex CLI with validation</li><li>Plugin inventory from <code>codex plugin list</code></li><li>Plugin install/remove where the installed Codex CLI exposes safe commands</li></ul></li><li><strong>Codex Backup Export</strong>: <ul><li>Redacted export-only backups for config, profile files, rules, and provider inventory metadata</li></ul></li><li><strong>Projects</strong>: <ul><li>Easier project discovery and directory browsing when adding project paths</li></ul></li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Provider status, capabilities, diagnostics, and normalized provider errors now drive more of the UI.</li><li>The frontend toolchain now uses TypeScript 6, <code>@vitejs/plugin-react</code> 5, updated ESLint tooling, React DOM, PostCSS, Tailwind Merge, and Node types.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>Codex auth, history, model cache, SQLite state, prompt text, and raw cache payloads are still excluded from raw viewers and backups.</li><li>Automatic Codex restore remains disabled because exports intentionally omit provider-owned local state.</li></ul><h2 id="_1-2-0-—-2026-04-22" tabindex="-1">1.2.0 — 2026-04-22 <a class="header-anchor" href="#_1-2-0-—-2026-04-22" aria-label="Permalink to &quot;1.2.0 — 2026-04-22&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>CC Bridge</strong> — live terminal bridge to Claude Code sessions in tmux <ul><li>Multi-terminal grid (up to 4 panes in auto-layout)</li><li>Per-pane read-only/interactive mode, fullscreen, attach/detach</li><li>Session discovery via <code>tmux list-panes</code> with auto-refresh</li><li>Spawn new sessions (plain, worktree, or resume mode)</li><li>Kill sessions with optional worktree cleanup</li><li>WebSocket PTY relay with xterm.js (WebGL rendering)</li></ul></li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>CC Bridge</strong> — prevent orphaned <code>tmux attach-session</code> processes on server reload</li><li><strong>CC Bridge</strong> — fix terminal rendering in React StrictMode</li></ul><h2 id="_1-0-0-—-2026-01-22" tabindex="-1">1.0.0 — 2026-01-22 <a class="header-anchor" href="#_1-0-0-—-2026-01-22" aria-label="Permalink to &quot;1.0.0 — 2026-01-22&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial release of Claude Deck</li><li><strong>Dashboard</strong> — configuration status and usage overview</li><li><strong>MCP Server Management</strong> — add, edit, test, configure servers (global + project)</li><li><strong>Commands</strong> — create and manage slash commands</li><li><strong>Plugins</strong> — create, install, and manage plugins</li><li><strong>Hooks</strong> — configure event hooks for Claude Code lifecycle</li><li><strong>Permissions</strong> — manage allow/deny rules for tools</li><li><strong>Backup &amp; Restore</strong> — full configuration backup and restore</li><li><strong>Project Management</strong> — project-specific configurations</li><li><strong>Usage Tracking</strong> — token usage and cost visualization</li></ul><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><ul><li>FastAPI backend with async SQLAlchemy + SQLite</li><li>React frontend with TypeScript, Vite, and shadcn/ui</li><li>RESTful API at <code>/api/v1/</code></li></ul><hr><p>See the full changelog on <a href="https://github.com/adrirubio/claude-deck/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">GitHub</a>.</p>',35)])])}const f=a(t,[["render",r]]);export{g as __pageData,f as default};
